import os

from django.conf import settings
from django.core.files import File
from django.core.files.storage import default_storage
from django.db import migrations, models


# The 3 banners the homepage hero slider has always shipped with, as static
# files bundled in the repo. Saving them to file storage and creating
# matching rows here means the dashboard's new Banner page starts pre-
# populated with today's actual site instead of an empty formset, so
# nothing changes visually until an admin edits it.
_SOURCE_STATIC_DIR = os.path.join(settings.BASE_DIR, 'myapp', 'static', 'img')
_SEED_FILES = ['banner1.webp', 'banner2.webp', 'banner3.webp']


def seed_hero_images(apps, schema_editor):
    HeroSlideImage = apps.get_model('myapp', 'HeroSlideImage')
    if HeroSlideImage.objects.exists():
        return
    for order, filename in enumerate(_SEED_FILES):
        src = os.path.join(_SOURCE_STATIC_DIR, filename)
        if not os.path.isfile(src):
            continue
        name = 'hero/' + filename
        if not default_storage.exists(name):
            with open(src, 'rb') as fh:
                name = default_storage.save(name, File(fh))
        HeroSlideImage.objects.create(image=name, order=order)


